changeSet.sql:
UPDATE theme SET layout = $J${
  "tiles": {
    "freshness":    { "col": 2,  "row": 1,  "colSpan": 3,  "rowSpan": 3 },
    "waveSwitcher": { "col": 6,  "row": 1,  "colSpan": 4,  "rowSpan": 3 },
    "music":        { "col": 12, "row": 1,  "colSpan": 8,  "rowSpan": 4 },
    "latestDrop":   { "col": 31, "row": 1,  "colSpan": 10, "rowSpan": 11 },
    "calendar":     { "col": 2,  "row": 5,  "colSpan": 9,  "rowSpan": 11 },
    "today":        { "col": 12, "row": 6,  "colSpan": 16, "rowSpan": 16 },
    "identity":     { "col": 34, "row": 13, "colSpan": 6,  "rowSpan": 3 },
    "stats":        { "col": 33, "row": 13, "colSpan": 8,  "rowSpan": 4 },
    "photoDrops":   { "col": 29, "row": 13, "colSpan": 3,  "rowSpan": 9 },
    "projects":     { "col": 2,  "row": 17, "colSpan": 9,  "rowSpan": 5 },
    "ride":         { "col": 33, "row": 18, "colSpan": 8,  "rowSpan": 7 },
    "marquee":      { "col": 4,  "row": 23, "colSpan": 15, "rowSpan": 5 },
    "social":       { "col": 21, "row": 23, "colSpan": 7,  "rowSpan": 5 },
    "hero":         { "col": 29, "row": 23, "colSpan": 3,  "rowSpan": 5 }
  },
  "mobileOrder": ["today", "calendar", "ride", "music", "stats", "photoDrops", "latestDrop", "projects", "social", "hero", "marquee", "freshness"]
}$J$::jsonb
WHERE key = 'wave-02';
